4	export async function GET(request: NextRequest) {
5	  const { searchParams } = new URL(request.url);
6	  const q = searchParams.get("q") ?? "";
7	  const categoryId = searchParams.get("categoryId") ?? "";
8	
9	  const where: Record<string, unknown> = {};
10	  if (q) {
11	    where.OR = [
12	      { name: { contains: q } },
13	      { code: { contains: q } },
14	      { model: { contains: q } },
15	      { sn: { contains: q } },
16	    ];
17	  }
18	  if (categoryId) {
19	    where.categoryId = categoryId;
20	  }
21	
22	  const items = await prisma.item.findMany({
23	    where,
24	    include: { category: true },
25	    orderBy: { updatedAt: "desc" },
26	  });
27	  return NextResponse.json(items);
28	}
