1	import { NextResponse } from "next/server";
2	import { prisma } from "@/lib/prisma";
3	
4	// DELETE 撤销单条记录，反向操作恢复库存
5	export async function DELETE(
6	  request: Request,
7	  { params }: { params: Promise<{ id: string }> }
8	) {
9	  const { id } = await params;
10	
11	  try {
12	    await prisma.$transaction(async (tx) => {
13	      const txn = await tx.transaction.findUnique({ where: { id } });
14	      if (!txn) {
15	        throw new Error("记录不存在");
16	      }
17	
18	      // 反向操作恢复库存
19	      const qtyChange = txn.type === "IN" ? -txn.quantity : txn.quantity;
20	
21	      await tx.item.update({
22	        where: { id: txn.itemId },
23	        data: { quantity: { increment: qtyChange } },
24	      });
25	      await tx.transaction.delete({ where: { id } });
26	    });
27	
28	    return NextResponse.json({ success: true });
29	  } catch (e) {
30	    const message = e instanceof Error ? e.message : "撤销失败";
31	    const status = message === "记录不存在" ? 404 : 400;
32	    return NextResponse.json({ error: message }, { status });
33	  }
34	}
