4	// PUT 更新单条盘点记录
5	export async function PUT(
6	  request: Request,
7	  { params }: { params: Promise<{ id: string }> }
8	) {
9	  const { id } = await params;
10	  const data = await request.json();
11	
12	  try {
13	    const record = await prisma.stockTake.findUnique({ where: { id } });
14	    if (!record) {
15	      return NextResponse.json({ error: "记录不存在" }, { status: 404 });
16	    }
17	
18	    const actualQuantity = data.actualQuantity;
19	    const difference = actualQuantity - record.expectedQuantity;
20	
21	    const updated = await prisma.stockTake.update({
22	      where: { id },
23	      data: { actualQuantity, difference, note: data.note },
24	    });
25	    return NextResponse.json(updated);
26	  } catch {
27	    return NextResponse.json({ error: "更新失败" }, { status: 400 });
28	  }
29	}
