31	// POST 完成盘点 — 更新所有记录对应的 Item.quantity
32	export async function POST(
33	  request: Request,
34	  { params }: { params: Promise<{ id: string }> }
35	) {
36	  const { id: batchId } = await params;
37	
38	  try {
39	    const records = await prisma.stockTake.findMany({
40	      where: { batchId },
41	    });
42	
43	    if (records.length === 0) {
44	      return NextResponse.json({ error: "批次不存在" }, { status: 404 });
45	    }
46	
47	    await Promise.all(
48	      records.map((r) =>
49	        prisma.item.update({
50	          where: { id: r.itemId },
51	          data: { quantity: r.actualQuantity },
52	        })
53	      )
54	    );
55	
56	    return NextResponse.json({ success: true });
57	  } catch {
58	    return NextResponse.json({ error: "完成盘点失败" }, { status: 400 });
59	  }
60	}
