47	export default function ItemDetailPage() {
48	  const { id } = useParams<{ id: string }>();
49	  const [item, setItem] = useState<Item | null>(null);
50	  const [error, setError] = useState<string | null>(null);
51	
52	  useEffect(() => {
53	    fetch(`/api/items/${id}`)
54	      .then((res) => res.json())
55	      .then((data) => {
56	        if (data.error) {
57	          setError(data.error);
58	        } else {
59	          setItem(data);
60	        }
61	      })
62	      .catch(() => setError("加载失败"));
63	  }, [id]);
64	
65	  if (error) {
66	    return (
67	      <div className="p-6 max-w-4xl mx-auto text-center">
68	        <p className="text-red-600 mb-4">{error}</p>
69	        <Link href="/items">
70	          <Button variant="outline">&larr; 返回列表</Button>
71	        </Link>
72	      </div>
73	    );
74	  }
75	
76	  if (!item) return <div className="p-6">加载中...</div>;
