75	export default function StockTakePage() {
76	  const [categories, setCategories] = useState<Category[]>([]);
77	  const [categoryId, setCategoryId] = useState("");
78	  const [records, setRecords] = useState<StockTakeRecord[]>([]);
79	  const [batchId, setBatchId] = useState<string | null>(null);
80	  const [completed, setCompleted] = useState(false);
81	  const [history, setHistory] = useState<BatchItem[]>([]);
82	  const [viewBatch, setViewBatch] = useState<string | null>(null);
83	
84	  useEffect(() => {
85	    fetch("/api/categories").then((r) => r.json()).then(setCategories);
86	    loadHistory();
87	  }, []);
88	
89	  const loadHistory = async () => {
90	    const res = await fetch("/api/stocktake");
91	    setHistory(await res.json());
92	  };
93	
94	  const startStockTake = async () => {
95	    const res = await fetch("/api/stocktake", {
96	      method: "POST",
97	      headers: { "Content-Type": "application/json" },
98	      body: JSON.stringify({ categoryId: categoryId || null }),
99	    });
100	    const data = await res.json();
101	    setBatchId(data.batchId);
102	    setCompleted(false);
103	    loadRecords(data.batchId);
104	  };
105	
106	  const loadRecords = async (bid: string) => {
107	    const res = await fetch(`/api/stocktake?batchId=${bid}`);
108	    setRecords(await res.json());
109	  };
110	
111	  const updateRecord = async (id: string, actualQuantity: number, note: string) => {
112	    await fetch(`/api/stocktake/${id}`, {
113	      method: "PUT",
114	      headers: { "Content-Type": "application/json" },
115	      body: JSON.stringify({ actualQuantity, note }),
116	    });
117	  };
118	
119	  const completeStockTake = async () => {
120	    if (!batchId) return;
121	    if (!confirm("确定完成盘点？库存将更新为实际数量。")) return;
122	    await fetch(`/api/stocktake/${batchId}`, { method: "POST" });
123	    setCompleted(true);
124	    loadHistory();
125	  };
126	
127	  if (viewBatch) {
128	    return <HistoryDetail batchId={viewBatch} onBack={() => setViewBatch(null)} />;
129	  }
130	
131	  // 正在进行中的盘点
132	  if (batchId && !completed) {
133	    return (
134	      <div className="p-6 max-w-4xl mx-auto">
135	        <div className="flex items-center justify-between mb-6">
136	          <h1 className="text-2xl font-bold">盘点中</h1>
137	          <Button onClick={completeStockTake}>完成盘点</Button>
138	        </div>
139	
140	        <div className="space-y-3">
141	          {records.map((r) => (
142	            <Card key={r.id}>
143	              <CardContent className="p-4">
144	                <div className="flex items-center justify-between">
145	                  <div className="flex-1">
146	                    <p className="font-semibold">{r.item.name}</p>
147	                    <p className="text-sm text-muted-foreground">
148	                      {r.item.code} | {r.item.position ?? "位置未知"} | 账面: {r.expectedQuantity} {r.item.unit}
149	                    </p>
150	                  </div>
151	                  <div className="flex items-center gap-3">
152	                    <Input
153	                      type="number"
154	                      className="w-20"
155	                      value={r.actualQuantity}
156	                      onChange={(e) => {
157	                        const val = parseInt(e.target.value) || 0;
158	                        setRecords((prev) =>
159	                          prev.map((x) =>
160	                            x.id === r.id
161	                              ? { ...x, actualQuantity: val, difference: val - x.expectedQuantity }
162	                              : x
163	                          )
164	                        );
165	                      }}
166	                      onBlur={(e) => {
167	                        const val = parseInt(e.target.value) || 0;
168	                        updateRecord(r.id, val, r.note ?? "");
169	                      }}
170	                    />
171	                    <span className="text-sm text-muted-foreground">{r.item.unit}</span>
172	                    {r.difference !== 0 && (
173	                      <Badge variant={r.difference < 0 ? "destructive" : "default"}>
174	                        {r.difference > 0 ? "+" : ""}{r.difference}
175	                      </Badge>
176	                    )}
177	                    {r.difference === 0 && <Badge variant="outline">OK</Badge>}
178	                  </div>
179	                </div>
180	              </CardContent>
181	            </Card>
182	          ))}
183	        </div>
184	      </div>
185	    );
186	  }
187	
188	  // 发起盘点页面
189	  return (
190	    <div className="p-6 max-w-3xl mx-auto">
191	      <h1 className="text-2xl font-bold mb-6">盘点</h1>
192	
193	      <Card className="mb-6">
194	        <CardHeader><CardTitle>发起新盘点</CardTitle></CardHeader>
195	        <CardContent>
196	          <div className="flex gap-3 items-end">
197	            <div className="flex-1">
198	              <Select
199	                value={categoryId || "null"}
200	                onValueChange={(v) => setCategoryId(!v || v === "null" ? "" : v)}
201	              >
202	                <SelectTrigger>
203	                  <SelectValue placeholder="全盘（所有物料）" />
204	                </SelectTrigger>
205	                <SelectContent>
206	                  <SelectItem value="null">全盘（所有物料）</SelectItem>
207	                  {categories.map((c) => (
208	                    <SelectItem key={c.id} value={c.id}>{c.name}</SelectItem>
209	                  ))}
210	                </SelectContent>
211	              </Select>
212	            </div>
213	            <Button onClick={startStockTake}>开始盘点</Button>
214	          </div>
215	        </CardContent>
216	      </Card>
217	
218	      <Card>
219	        <CardHeader><CardTitle>盘点历史</CardTitle></CardHeader>
220	        <CardContent>
221	          {history.map((batch) => (
222	            <div
223	              key={batch.batchId}
224	              className="flex justify-between items-center py-2 border-b last:border-0 cursor-pointer hover:bg-muted/50 px-2 rounded"
225	              onClick={() => setViewBatch(batch.batchId)}
226	            >
227	              <div>
228	                <p className="font-medium">
229	                  {new Date(batch._min.createdAt).toLocaleString("zh-CN")}
230	                </p>
231	                <p className="text-sm text-muted-foreground">
232	                  {batch._count.id} 项物料
233	                </p>
234	              </div>
235	              <Button variant="ghost" size="sm">查看</Button>
236	            </div>
237	          ))}
238	          {history.length === 0 && (
239	            <p className="text-center text-muted-foreground py-4">暂无盘点记录</p>
240	          )}
241	        </CardContent>
242	      </Card>
243	    </div>
