9	
10	interface Row {
11	  itemId: string;
12	  itemName: string;
13	  unit: string;
14	  quantity: number;
15	  reason: string;
16	  relatedPerson: string;
17	  note: string;
18	}
19	
20	interface Props {
21	  type: "IN" | "OUT";
22	}
23	
24	const emptyRow: Row = {
25	  itemId: "", itemName: "", unit: "", quantity: 1,
26	  reason: "", relatedPerson: "", note: "",
27	};
28	
29	export function TransactionForm({ type }: Props) {
30	  const router = useRouter();
31	  const [rows, setRows] = useState<Row[]>([{ ...emptyRow }]);
32	  const [submitting, setSubmitting] = useState(false);
33	
34	  const title = type === "IN" ? "入库" : "出库";
35	
36	  const addRow = () => {
37	    setRows([...rows, { ...emptyRow }]);
38	  };
39	
40	  const removeRow = (i: number) => {
41	    if (rows.length === 1) return;
42	    setRows(rows.filter((_, idx) => idx !== i));
43	  };
44	
45	  const updateRow = (i: number, field: keyof Row, value: string | number) => {
46	    setRows((prev) => {
47	      const next = [...prev];
48	      next[i] = { ...next[i], [field]: value };
49	      return next;
50	    });
51	  };
52	
53	  const handleSubmit = async () => {
54	    const valid = rows.filter((r) => r.itemId && r.quantity > 0);
55	    if (valid.length === 0) return;
56	
57	    setSubmitting(true);
58	    const body = {
59	      type,
60	      items: valid.map((r) => ({
61	        itemId: r.itemId,
62	        quantity: r.quantity,
63	        reason: r.reason,
64	        relatedPerson: r.relatedPerson,
65	        note: r.note,
66	      })),
67	    };
68	
69	    const res = await fetch("/api/transactions", {
70	      method: "POST",
71	      headers: { "Content-Type": "application/json" },
72	      body: JSON.stringify(body),
73	    });
74	
75	    if (!res.ok) {
76	      const err = await res.json();
77	      alert(err.error);
78	      setSubmitting(false);
79	      return;
80	    }
81	
82	    router.push("/transactions/history");
83	  };
84	
85	  return (
86	    <div className="p-6 max-w-3xl mx-auto">
87	      <h1 className="text-2xl font-bold mb-6">{title}</h1>
88	
89	      <Card className="mb-4">
90	        <CardContent className="p-4">
91	          {rows.map((row, i) => (
92	            <div
93	              key={i}
94	              className="grid grid-cols-1 md:grid-cols-12 gap-2 mb-3 pb-3 border-b last:border-0"
95	            >
96	              <div className="md:col-span-3">
97	                <label className="text-xs font-medium">物料</label>
98	                <ItemSelector
99	                  value={row.itemId}
100	                  onChange={(item) => {
101	                    updateRow(i, "itemId", item.id);
102	                    updateRow(i, "itemName", item.name);
103	                    updateRow(i, "unit", item.unit);
104	                  }}
105	                />
106	              </div>
107	              <div className="md:col-span-2">
108	                <label className="text-xs font-medium">数量</label>
109	                <div className="flex items-center gap-1">
110	                  <Input
111	                    type="number"
112	                    min={1}
113	                    value={row.quantity}
114	                    onChange={(e) => updateRow(i, "quantity", parseInt(e.target.value) || 0)}
115	                  />
116	                  <span className="text-sm text-muted-foreground shrink-0">{row.unit}</span>
117	                </div>
118	              </div>
119	              <div className="md:col-span-2">
120	                <label className="text-xs font-medium">领用人</label>
121	                <Input
122	                  value={row.relatedPerson}
123	                  onChange={(e) => updateRow(i, "relatedPerson", e.target.value)}
124	                  placeholder="可选"
125	                />
126	              </div>
127	              <div className="md:col-span-3">
128	                <label className="text-xs font-medium">用途</label>
129	                <Input
130	                  value={row.reason}
131	                  onChange={(e) => updateRow(i, "reason", e.target.value)}
132	                  placeholder="可选"
133	                />
134	              </div>
135	              <div className="md:col-span-1">
136	                <label className="text-xs font-medium">备注</label>
137	                <Input
138	                  value={row.note}
139	                  onChange={(e) => updateRow(i, "note", e.target.value)}
140	                  placeholder="可选"
141	                />
142	              </div>
143	              <div className="md:col-span-1 flex items-end">
144	                <Button
145	                  variant="ghost" size="sm"
146	                  onClick={() => removeRow(i)}
147	                  disabled={rows.length === 1}
148	                >
149	                  删除
150	                </Button>
151	              </div>
152	            </div>
153	          ))}
154	
155	          <Button variant="outline" size="sm" onClick={addRow} className="mt-2">
156	            + 添加物料
157	          </Button>
158	        </CardContent>
159	      </Card>
160	
161	      <div className="flex justify-end gap-2">
162	        <Button variant="outline" onClick={() => router.back()}>取消</Button>
163	        <Button
164	          onClick={handleSubmit}
165	          disabled={submitting || rows.every((r) => !r.itemId)}
166	        >
167	          {submitting ? "提交中..." : `确认${title}`}
168	        </Button>
169	      </div>
170	    </div>
171	  );
172	}
