28	export function CategoryFormDialog({
29	  open, onOpenChange, category, categories, onSaved,
30	}: Props) {
31	  const [name, setName] = useState("");
32	  const [parentId, setParentId] = useState<string | null>(null);
33	  const [description, setDescription] = useState("");
34	  const [saving, setSaving] = useState(false);
35	
36	  useEffect(() => {
37	    if (category) {
38	      setName(category.name);
39	      setParentId(category.parentId);
40	      setDescription(category.description ?? "");
